package plotly

import java.lang.reflect.Modifier

import plotly.element._
import plotly.layout._

// The with* setters of @data classes are generated by the @data macro on Scala 2, and
// by DataSetters in build.mill on Scala 3
class SettersTests extends munit.FunSuite {

  // @data classes, and whether they have option setters
  val classes = Seq[(Class[_], Boolean)](
    classOf[Scatter]                -> true,
    classOf[Box]                    -> true,
    classOf[Image]                  -> true,
    classOf[Bar]                    -> true,
    classOf[Histogram]              -> true,
    classOf[Surface]                -> true,
    classOf[Heatmap]                -> true,
    classOf[Candlestick]            -> true,
    classOf[Config]                 -> true,
    classOf[Annotation]             -> true,
    classOf[Axis]                   -> true,
    classOf[Font]                   -> true,
    classOf[Grid]                   -> true,
    classOf[Layout]                 -> true,
    classOf[Legend]                 -> true,
    classOf[Margin]                 -> true,
    classOf[RangeSlider]            -> true,
    classOf[Scene]                  -> true,
    classOf[Shape]                  -> true,
    classOf[Error.Data]             -> true,
    classOf[Error.Percent]          -> true,
    classOf[Error.Constant]         -> true,
    classOf[HoverLabel]             -> true,
    classOf[HoverLabelFont]         -> true,
    classOf[Line]                   -> true,
    classOf[Marker]                 -> true,
    classOf[AxisAnchor.Reference]   -> false,
    classOf[Bins]                   -> false,
    classOf[BoxMean.Bool]           -> false,
    classOf[BoxPoints.Bool]         -> false,
    classOf[Color.HSL]              -> false,
    classOf[Color.RGB]              -> false,
    classOf[Color.RGBA]             -> false,
    classOf[Color.StringColor]      -> false,
    classOf[ColorScale.CustomScale] -> false,
    classOf[ColorScale.NamedScale]  -> false,
    classOf[Cumulative]             -> false,
    classOf[LocalDateTime]          -> false,
    classOf[ScatterMode]            -> false,
    classOf[Symbol.Circle]          -> false,
    classOf[Symbol.Cross]           -> false,
    classOf[Symbol.Diamond]         -> false,
    classOf[Symbol.Square]          -> false,
    classOf[TextFont]               -> false
  )

  for ((cls, optionSetters) <- classes)
    test(s"${cls.getName} has setters for all its fields") {
      val fields  = cls.getDeclaredFields.toSeq.filter(f => !Modifier.isStatic(f.getModifiers))
      val setters = cls.getMethods.toSeq.filter(_.getName.startsWith("with")).groupBy(_.getName)
      assert(fields.nonEmpty)
      for (field <- fields) {
        val setterName  = "with" + field.getName.capitalize
        val setters0    = setters.getOrElse(setterName, Nil)
        val paramTypes  = setters0.map(_.getParameterTypes.toSeq).toSet
        val returnTypes = setters0.map(_.getReturnType).toSet
        assert(paramTypes.contains(Seq(field.getType)), s"No $setterName(${field.getType.getName}) method in $cls")
        val expectedCount = if (optionSetters && field.getType == classOf[Option[_]]) 2 else 1
        assertEquals(setters0.length, expectedCount, s"$setterName methods in $cls: ${setters0.mkString(", ")}")
        assertEquals(returnTypes, Set[Class[_]](cls))
      }
      assertEquals(setters.keySet, fields.map("with" + _.getName.capitalize).toSet)
    }

  test("setters update a single field") {
    val marker = Marker()
      .withSize(3)
      .withColor(Some(OneOrSeq.One[Color](Color.RGB(1, 2, 3))))
      .withSizeref(2.0)
    assertEquals(marker.size, Some(OneOrSeq.One(3)))
    assertEquals(marker.color, Some(OneOrSeq.One[Color](Color.RGB(1, 2, 3))))
    assertEquals(marker.sizeref, Some(2.0))
    assertEquals(marker.withSize(None), Marker().withColor(Color.RGB(1, 2, 3)).withSizeref(2.0))
    assertEquals(Color.RGB(1, 2, 3).withG(4), Color.RGB(1, 4, 3))
    assertEquals(Error.Data(Seq(1.0)).withVisible(true).visible, Some(true))
  }
}
